entries.syntax:
SELECT [DISTINCT] <expressions> [FROM <source>] [WHERE <condition>];
SELECT * EXCLUDE(column_b) FROM source;
SELECT * REPLACE(column_a + 1 AS column_a) FROM source;
SELECT * RENAME column_a AS renamed FROM source;

WITH cte_name [(column_list)] AS (SELECT ...),
     next_cte AS (SELECT ... FROM cte_name)
SELECT ... FROM next_cte;

entries.example:
WITH base AS (
  SELECT column1 AS n FROM VALUES (1), (2)
), doubled AS (
  SELECT n * 2 AS n FROM base
)
SELECT n FROM doubled ORDER BY n;

SELECT a.id, b.label
FROM (VALUES (1), (2)) a(id)
LEFT JOIN (VALUES (1, 'one')) b(id, label) ON a.id = b.id;

SELECT column1 AS kind, COUNT(*) AS n
FROM VALUES ('a'), ('a'), ('b')
GROUP BY column1 HAVING COUNT(*) > 1;

SELECT column1, ROW_NUMBER() OVER (ORDER BY column1) AS rn
FROM VALUES (3), (1), (2)
QUALIFY rn <= 2;

UPDATE users AS t SET name = s.name
FROM (VALUES (1, 'Alice')) s(id, name)
WHERE t.id = s.id;

entries.syntax:
MERGE INTO target USING source ON condition
WHEN MATCHED THEN UPDATE SET ...
WHEN NOT MATCHED THEN INSERT (...) VALUES (...);

entries.example:
MERGE INTO users t USING incoming s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET name = s.name
WHEN NOT MATCHED THEN INSERT (id, name) VALUES (s.id, s.name);

entries.syntax:
CREATE [OR REPLACE] STAGE [IF NOT EXISTS] name [COMMENT = 'text'];
SHOW STAGES;
LIST @name[/path] [PATTERN = '*.csv'];
DROP STAGE [IF EXISTS] name;

entries.example:
CREATE TEMPORARY TABLE doubled AS
WITH base AS (SELECT column1 AS n FROM VALUES (1), (2))
SELECT n * 2 AS n FROM base;

entries.syntax:
ALTER TABLE name ADD COLUMN column_name type [DEFAULT value];
ALTER TABLE name RENAME COLUMN old_name TO new_name;
ALTER TABLE name ALTER COLUMN column_name TYPE type;
ALTER TABLE name DROP COLUMN column_name;
TRUNCATE TABLE name;
DROP TABLE [IF EXISTS] name;

CREATE DATABASE [IF NOT EXISTS] name [COMMENT = 'text'];
CREATE SCHEMA [IF NOT EXISTS] database_name.schema_name [COMMENT = 'text'];
DROP DATABASE [IF EXISTS] name [CASCADE|RESTRICT];
DROP SCHEMA [IF EXISTS] database_name.schema_name [CASCADE|RESTRICT];

CREATE [OR REPLACE] VIEW name [(column_a, column_b)] AS query;
SHOW VIEWS;
DROP VIEW [IF EXISTS] name;

CREATE [OR REPLACE] DYNAMIC TABLE name TARGET_LAG = '1 MINUTE' WAREHOUSE = wh AS query;
ALTER DYNAMIC TABLE name REFRESH;
SHOW DYNAMIC TABLES;
DROP DYNAMIC TABLE [IF EXISTS] name;

entries.example:
CREATE DYNAMIC TABLE user_summary
TARGET_LAG = '1 MINUTE' WAREHOUSE = COMPUTE_WH
AS SELECT COUNT(*) AS total FROM users;

entries.syntax:
CREATE WAREHOUSE name WAREHOUSE_SIZE = 'X-SMALL' AUTO_RESUME = TRUE AUTO_SUSPEND = 600;
ALTER WAREHOUSE name SET WAREHOUSE_SIZE = 'SMALL' AUTO_RESUME = TRUE AUTO_SUSPEND = 60;
ALTER WAREHOUSE name {RESUME|SUSPEND};
SHOW WAREHOUSES;
DROP WAREHOUSE [IF EXISTS] name;

SET name = expression;
SELECT $name;
UNSET name;

entries.example:
SET threshold = 10;
SELECT $threshold + 1;
UNSET threshold;

entries.syntax:
BEGIN; -- or START TRANSACTION
COMMIT;
ROLLBACK;

entries.example:
BEGIN;
INSERT INTO users VALUES (1, 'Alice');
COMMIT;

entries.syntax:
SHOW TABLES;
DESCRIBE TABLE name;
EXPLAIN SELECT ...;

entries.example:
SHOW TABLES;
DESCRIBE TABLE users;
EXPLAIN SELECT * FROM users;

entries.syntax:
CREATE USER [IF NOT EXISTS] name PASSWORD = 'password' [DEFAULT_ROLE = role_name] [DISABLED = FALSE] [COMMENT = 'text'];
ALTER USER name SET PASSWORD = 'password' DEFAULT_ROLE = role_name DISABLED = FALSE COMMENT = 'text';
DROP USER [IF EXISTS] name;
CREATE ROLE [IF NOT EXISTS] name [COMMENT = 'text'];
DROP ROLE [IF EXISTS] name;
SHOW USERS;
SHOW ROLES;

GRANT ROLE child TO {USER|ROLE} parent;
REVOKE ROLE child FROM {USER|ROLE} parent;
GRANT privilege ON object_type name TO ROLE role_name;
REVOKE privilege ON object_type name FROM ROLE role_name;
SHOW GRANTS TO USER user_name;
SHOW GRANTS TO ROLE role_name;
SHOW GRANTS OF ROLE role_name;

CREATE [OR REPLACE] FUNCTION name(args) RETURNS type [LANGUAGE SQL] AS $$ expression $$;
SHOW FUNCTIONS;
DROP FUNCTION [IF EXISTS] name(types);

CREATE [OR REPLACE] PROCEDURE name(args) RETURNS type LANGUAGE SQL AS $$ BEGIN ... END; $$;
CALL name(args);
SHOW PROCEDURES;
DROP PROCEDURE name;

entries.example:
CREATE PROCEDURE greeting() RETURNS VARCHAR LANGUAGE SQL
AS $$ BEGIN RETURN 'hello'; END; $$;
CALL greeting();

entries.syntax:
DECLARE variable type DEFAULT expression;
BEGIN
  LET other type := expression;
  variable := expression;
  IF (condition) THEN ... ELSE ... END IF;
  RETURN expression;
END;

entries.example:
CREATE PROCEDURE answer() RETURNS INTEGER LANGUAGE SQL
AS $$ BEGIN LET n INTEGER := 40; RETURN n + 2; END; $$;
CALL answer();

entries.syntax:
CREATE [OR REPLACE] STREAM name ON TABLE source [APPEND_ONLY = TRUE];
SELECT *, "METADATA$ACTION", "METADATA$ISUPDATE", "METADATA$ROW_ID" FROM name;
SHOW STREAMS;
DROP STREAM [IF EXISTS] name;

CREATE [OR REPLACE] TASK name WAREHOUSE = wh SCHEDULE = '1 MINUTE' AS sql;
ALTER TASK name RESUME;
ALTER TASK name SUSPEND;
EXECUTE TASK name;
SHOW TASKS;
DROP TASK [IF EXISTS] name;

entries.example:
CREATE TASK refresh_users WAREHOUSE = COMPUTE_WH
SCHEDULE = '1 MINUTE' AS INSERT INTO users VALUES (1, 'Alice');
ALTER TASK refresh_users RESUME;

SELECT * FROM (VALUES ('item', 'q1', 10), ('item', 'q2', 20))
  t(item, quarter, amount)
PIVOT(SUM(amount) FOR quarter IN ('q1', 'q2'));

entries.syntax:
function(...) OVER (
  [PARTITION BY key] ORDER BY expression
  [ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW]
)

entries.example:
SELECT * FROM (VALUES (1, 3)) l(id, ts)
ASOF JOIN (VALUES (1, 2)) r(id, ts)
ON l.ts >= r.ts AND l.id = r.id;

CREATE PROCEDURE dynamic_example() RETURNS INTEGER LANGUAGE SQL AS $$
DECLARE table_name VARCHAR DEFAULT 'dynamic_rows';
BEGIN
  CREATE TEMPORARY TABLE IDENTIFIER(:table_name) (id INTEGER);
  INSERT INTO IDENTIFIER(:table_name) VALUES (1);
  RETURN SQLROWCOUNT;
END;
$$;
CALL dynamic_example();

CREATE PROCEDURE inserted_rows() RETURNS INTEGER LANGUAGE SQL AS $$
BEGIN
  CREATE TEMPORARY TABLE status_rows (id INTEGER);
  INSERT INTO status_rows VALUES (1), (2);
  RETURN SQLROWCOUNT;
END;
$$;
CALL inserted_rows();
